INSERT IGNORE INTO `tb_question` (`question_id`, `title`, `difficulty`, `purpose`, `time_limit`, `space_limit`, `content`, `default_code`, `main_func`, `create_by`, `create_time`) VALUES
(1794933791345602562, '两数之和', 1, 1, 1000, 128, '给定一个整数数组 `nums` 和一个整数目标值 `target`，请你在该数组中找出和为目标值 `target` 的那两个整数，并返回它们的数组下标（按升序）。\n\n你可以假设每种输入只会对应一个答案，并且同一个元素在答案里不能重复出现。\n\n提示：\n- 2 <= nums.length <= 10^4\n- -10^9 <= nums[i] <= 10^9\n- 只会存在一个有效答案', 'public int[] twoSum(int[] nums, int target) {\n    // 请在此处编写你的代码\n    return new int[0];\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        int target = Integer.parseInt(in.readLine().trim());\n        int[] r = m.twoSum(nums, target);\n        if (r == null) {\n            System.out.println("null");\n        } else {\n            Arrays.sort(r);\n            System.out.println(Arrays.toString(r).replace(" ", ""));\n        }\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 518400 MINUTE)),
(1794900876543210003, '有效的括号', 1, 1, 1000, 128, '给定一个只包括 `(`、`)`、`{`、`}`、`[`、`]` 的字符串 `s`，判断字符串是否有效。\n\n有效字符串需满足：\n1. 左括号必须用相同类型的右括号闭合；\n2. 左括号必须以正确的顺序闭合；\n3. 每个右括号都有一个对应的相同类型的左括号。\n\n提示：\n- 1 <= s.length <= 10^4\n- s 仅由括号 ()[]{} 组成', 'public boolean isValid(String s) {\n    // 请在此处编写你的代码\n    return false;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        String s = in.readLine();\n        System.out.println(m.isValid(s));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 516960 MINUTE)),
(1796119683661783042, '回文数', 1, 1, 1000, 128, '给你一个整数 `x`，如果 `x` 是一个回文整数，返回 `true`；否则，返回 `false`。\n\n回文数是指正序（从左向右）和倒序（从右向左）读都是一样的整数，例如 121 是回文，而 123 不是。\n\n提示：\n- -2^31 <= x <= 2^31 - 1\n- 进阶：不将整数转为字符串来解决', 'public boolean isPalindrome(int x) {\n    // 请在此处编写你的代码\n    return false;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int x = Integer.parseInt(in.readLine().trim());\n        System.out.println(m.isPalindrome(x));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 515520 MINUTE)),
(1795000000000000104, '爬楼梯', 1, 1, 1000, 128, '假设你正在爬楼梯，需要 `n` 阶才能到达楼顶。\n\n每次你可以爬 1 或 2 个台阶。你有多少种不同的方法可以爬到楼顶呢？\n\n提示：\n- 1 <= n <= 45', 'public int climbStairs(int n) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int n = Integer.parseInt(in.readLine().trim());\n        System.out.println(m.climbStairs(n));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 514080 MINUTE)),
(1795000000000000105, '只出现一次的数字', 1, 1, 1000, 128, '给你一个非空整数数组 `nums`，除了某个元素只出现一次以外，其余每个元素均出现两次。找出那个只出现了一次的元素。\n\n你必须设计并实现线性时间复杂度的算法来解决此问题，且该算法只使用常量额外空间。\n\n提示：\n- 1 <= nums.length <= 3 * 10^4\n- -3 * 10^4 <= nums[i] <= 3 * 10^4\n- 除了某个元素只出现一次以外，其余每个元素均出现两次', 'public int singleNumber(int[] nums) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(m.singleNumber(nums));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 512640 MINUTE)),
(1795000000000000106, '二分查找', 1, 1, 1000, 128, '给定一个 `n` 个元素有序的（升序）整型数组 `nums` 和一个目标值 `target`，写一个函数搜索 `nums` 中的 `target`，如果目标值存在返回下标，否则返回 `-1`。\n\n提示：\n- nums 中的所有元素互不相同\n- 1 <= n <= 10^4\n- -10^4 <= nums[i], target <= 10^4', 'public int search(int[] nums, int target) {\n    // 请在此处编写你的代码\n    return -1;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        int target = Integer.parseInt(in.readLine().trim());\n        System.out.println(m.search(nums, target));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 511200 MINUTE)),
(2102360449353351170, '岛屿数量统计', 2, 1, 1000, 64, '给定一个由 `1`（陆地）和 `0`（水）组成的二维网格，请计算网格中岛屿的数量。\n\n岛屿总是被水包围，并且每座岛屿只能由水平方向和/或竖直方向上相邻的陆地连接形成。你可以假设网格的四条边均被水包围。\n\n提示：\n- 1 <= m, n <= 300\n- grid[i][j] 的值仅为 0 或 1', 'public int numIslands(char[][] grid) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int n = Integer.parseInt(in.readLine().trim());\n        char[][] grid = new char[n][];\n        for (int j = 0; j < n; j++) {\n            grid[j] = in.readLine().trim().toCharArray();\n        }\n        System.out.println(m.numIslands(grid));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 509760 MINUTE)),
(1795000000000000108, '无重复字符的最长子串', 2, 1, 1000, 128, '给定一个字符串 `s`，请你找出其中不含有重复字符的最长子串的长度。\n\n提示：\n- 1 <= s.length <= 5 * 10^4\n- s 由英文字母、数字、符号和空格组成', 'public int lengthOfLongestSubstring(String s) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        String s = in.readLine();\n        System.out.println(m.lengthOfLongestSubstring(s == null ? "" : s));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 508320 MINUTE)),
(1795000000000000109, '最长递增子序列', 2, 1, 1000, 128, '给你一个整数数组 `nums`，找到其中最长严格递增子序列的长度。\n\n子序列是由数组派生而来的序列，删除（或不删除）数组中的元素而不改变其余元素的顺序。\n\n提示：\n- 1 <= nums.length <= 2500\n- -10^4 <= nums[i] <= 10^4\n- 进阶：设计时间复杂度为 O(n log n) 的算法', 'public int lengthOfLIS(int[] nums) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(m.lengthOfLIS(nums));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 506880 MINUTE)),
(1795000000000000110, '零钱兑换', 2, 1, 1000, 128, '给你一个整数数组 `coins`，表示不同面额的硬币；以及一个整数 `amount`，表示总金额。\n\n计算并返回可以凑成总金额所需的最少硬币个数。如果没有任何一种硬币组合能组成总金额，返回 `-1`。你可以认为每种硬币的数量是无限的。\n\n提示：\n- 1 <= coins.length <= 12\n- 1 <= coins[i] <= 2^31 - 1\n- 0 <= amount <= 10^4', 'public int coinChange(int[] coins, int amount) {\n    // 请在此处编写你的代码\n    return -1;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] coins = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        int amount = Integer.parseInt(in.readLine().trim());\n        System.out.println(m.coinChange(coins, amount));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 505440 MINUTE));
INSERT IGNORE INTO `tb_question` (`question_id`, `title`, `difficulty`, `purpose`, `time_limit`, `space_limit`, `content`, `default_code`, `main_func`, `create_by`, `create_time`) VALUES
(1795000000000000111, '最大子数组和', 2, 1, 1000, 128, '给你一个整数数组 `nums`，请你找出一个具有最大和的连续子数组（子数组最少包含一个元素），返回其最大和。\n\n提示：\n- 1 <= nums.length <= 10^5\n- -10^4 <= nums[i] <= 10^4\n- 进阶：尝试使用分治法求解', 'public int maxSubArray(int[] nums) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(m.maxSubArray(nums));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 504000 MINUTE)),
(1795000000000000112, '接雨水', 3, 1, 1000, 128, '给定 `n` 个非负整数表示每个宽度为 1 的柱子的高度图，计算按此排列的柱子，下雨之后能接多少雨水。\n\n提示：\n- 1 <= n <= 2 * 10^4\n- 0 <= height[i] <= 10^5', 'public int trap(int[] height) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] height = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(m.trap(height));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 502560 MINUTE)),
(1795000000000000113, '编辑距离', 3, 1, 1000, 128, '给你两个单词 `word1` 和 `word2`，请返回将 `word1` 转换成 `word2` 所使用的最少操作数。\n\n你可以对一个单词进行如下三种操作：插入一个字符、删除一个字符、替换一个字符。\n\n提示：\n- 1 <= word1.length, word2.length <= 500\n- word1 和 word2 由小写英文字母组成', 'public int minDistance(String word1, String word2) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        String a = in.readLine().trim();\n        String b = in.readLine().trim();\n        System.out.println(m.minDistance(a, b));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 501120 MINUTE)),
(1795000000000000114, '最长有效括号', 3, 1, 1000, 128, '给你一个只包含 `(` 和 `)` 的字符串，找出最长有效（格式正确且连续）括号子串的长度。\n\n提示：\n- 1 <= s.length <= 3 * 10^4\n- s[i] 为 ( 或 )', 'public int longestValidParentheses(String s) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        String s = in.readLine().trim();\n        System.out.println(m.longestValidParentheses(s));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 499680 MINUTE)),
(1795000000000000115, 'N 皇后 II', 3, 1, 2000, 128, 'n 皇后问题研究的是如何将 `n` 个皇后放置在 `n × n` 的棋盘上，并且使皇后彼此之间不能相互攻击（任意两个皇后不在同一行、同一列或同一斜线上）。\n\n给你一个整数 `n`，返回 n 皇后问题不同的解决方案的数量。\n\n提示：\n- 1 <= n <= 9', 'public int totalNQueens(int n) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int n = Integer.parseInt(in.readLine().trim());\n        System.out.println(m.totalNQueens(n));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 498240 MINUTE)),
(1795000000000000116, '合并两个有序数组', 1, 1, 1000, 128, '给你两个按 **非递减顺序** 排列的整数数组 `nums1` 和 `nums2`，请将它们合并为一个同样按非递减顺序排列的新数组并返回。\n\n提示：\n- 1 <= nums1.length, nums2.length <= 200\n- -10^9 <= nums1[i], nums2[j] <= 10^9\n- 进阶：设计一个时间复杂度为 O(m + n) 的算法', 'public int[] merge(int[] nums1, int[] nums2) {\n    // 请在此处编写你的代码\n    return new int[0];\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] a = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        int[] b = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(Arrays.toString(m.merge(a, b)).replace(" ", ""));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 496800 MINUTE)),
(1795000000000000117, '移动零', 1, 2, 1000, 128, '给定一个数组 `nums`，编写一个函数将所有 `0` 移动到数组的末尾，同时保持非零元素的相对顺序。\n\n请注意，必须在不复制数组的情况下原地对数组进行操作。\n\n提示：\n- 1 <= nums.length <= 10^4\n- -2^31 <= nums[i] <= 2^31 - 1', 'public void moveZeroes(int[] nums) {\n    // 请在此处编写你的代码\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        m.moveZeroes(nums);\n        System.out.println(Arrays.toString(nums).replace(" ", ""));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 495360 MINUTE)),
(1795000000000000118, '反转字符串中的单词', 2, 1, 1000, 128, '给你一个字符串 `s`，请你反转字符串中 **单词** 的顺序。\n\n单词是由非空格字符组成的字符串，`s` 中使用至少一个空格将单词分隔开。返回单词顺序颠倒、单词之间用单个空格连接的结果字符串。\n\n注意：输入字符串可能在前面、后面或者单词间包含多个空格，返回的结果中不应包含多余的空格。\n\n提示：\n- 1 <= s.length <= 10^4\n- s 中至少存在一个单词', 'public String reverseWords(String s) {\n    // 请在此处编写你的代码\n    return "";\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        String s = in.readLine();\n        System.out.println(m.reverseWords(s));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 493920 MINUTE)),
(1795000000000000119, '杨辉三角 II', 1, 2, 1000, 128, '给定一个非负索引 `rowIndex`，返回「杨辉三角」的第 `rowIndex` 行（行号从 0 开始）。\n\n在「杨辉三角」中，每个数是它左上方和右上方的数的和。\n\n提示：\n- 0 <= rowIndex <= 33\n- 进阶：只使用 O(rowIndex) 的额外空间', 'public int[] getRow(int rowIndex) {\n    // 请在此处编写你的代码\n    return new int[0];\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int r = Integer.parseInt(in.readLine().trim());\n        System.out.println(Arrays.toString(m.getRow(r)).replace(" ", ""));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 492480 MINUTE)),
(1795000000000000120, '买卖股票的最佳时机', 1, 2, 1000, 128, '给定一个数组 `prices`，它的第 `i` 个元素 `prices[i]` 表示一支给定股票第 `i` 天的价格。\n\n你只能选择某一天买入这只股票，并选择在未来的某一个不同的日子卖出。返回你可以从这笔交易中获取的最大利润；如果你不能获取任何利润，返回 `0`。\n\n提示：\n- 1 <= prices.length <= 10^5\n- 0 <= prices[i] <= 10^4', 'public int maxProfit(int[] prices) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] prices = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(m.maxProfit(prices));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 491040 MINUTE));
INSERT IGNORE INTO `tb_question` (`question_id`, `title`, `difficulty`, `purpose`, `time_limit`, `space_limit`, `content`, `default_code`, `main_func`, `create_by`, `create_time`) VALUES
(1795000000000000121, '多数元素', 1, 2, 1000, 128, '给定一个大小为 `n` 的数组 `nums`，返回其中的多数元素。多数元素是指在数组中出现次数 **大于** `⌊ n/2 ⌋` 的元素。\n\n你可以假设数组是非空的，并且给定的数组总是存在多数元素。\n\n提示：\n- 1 <= n <= 5 * 10^4\n- -10^9 <= nums[i] <= 10^9\n- 进阶：尝试设计时间复杂度为 O(n)、空间复杂度为 O(1) 的算法', 'public int majorityElement(int[] nums) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(m.majorityElement(nums));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 489600 MINUTE)),
(1795000000000000122, '盛最多水的容器', 2, 1, 1000, 128, '给定一个长度为 `n` 的整数数组 `height`。有 `n` 条垂线，第 `i` 条线的两个端点是 `(i, 0)` 和 `(i, height[i])`。\n\n找出其中的两条线，使得它们与 x 轴共同构成的容器可以容纳最多的水，返回容器可以储存的最大水量。\n\n说明：你不能倾斜容器。\n\n提示：\n- 2 <= n <= 10^5\n- 0 <= height[i] <= 10^4', 'public int maxArea(int[] height) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] height = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(m.maxArea(height));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 488160 MINUTE)),
(1795000000000000123, '最长公共子序列', 2, 2, 1000, 128, '给定两个字符串 `text1` 和 `text2`，返回这两个字符串的最长 **公共子序列** 的长度；如果不存在公共子序列，返回 `0`。\n\n一个字符串的子序列是指由原字符串在不改变字符相对顺序的情况下删除某些字符（也可以不删除）后组成的新字符串，例如 "ace" 是 "abcde" 的子序列。\n\n提示：\n- 1 <= text1.length, text2.length <= 1000\n- text1 和 text2 仅由小写英文字母组成', 'public int longestCommonSubsequence(String text1, String text2) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        String a = in.readLine().trim();\n        String b = in.readLine().trim();\n        System.out.println(m.longestCommonSubsequence(a, b));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 486720 MINUTE)),
(1795000000000000124, '跳跃游戏', 2, 2, 1000, 128, '给你一个非负整数数组 `nums`，你最初位于数组的 **第一个下标**。数组中的每个元素代表你在该位置可以跳跃的最大长度。\n\n判断你是否能够到达最后一个下标，如果可以，返回 `true`；否则，返回 `false`。\n\n提示：\n- 1 <= nums.length <= 10^4\n- 0 <= nums[i] <= 10^5', 'public boolean canJump(int[] nums) {\n    // 请在此处编写你的代码\n    return false;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        System.out.println(m.canJump(nums));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 485280 MINUTE)),
(1795000000000000125, '合并区间', 2, 2, 1000, 128, '以数组 `intervals` 表示若干个区间的集合，其中单个区间为 `intervals[i] = [start, end]`。请你合并所有重叠的区间，并返回一个不重叠的区间数组，该数组需恰好覆盖输入中的所有区间，结果按区间起点升序排列。\n\n提示：\n- 1 <= intervals.length <= 10^4\n- 0 <= start <= end <= 10^4\n- 输入的区间不保证有序', 'public int[][] merge(int[][] intervals) {\n    // 请在此处编写你的代码\n    return new int[0][];\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        String[] parts = in.readLine().trim().split(";");\n        int[][] intervals = new int[parts.length][];\n        for (int j = 0; j < parts.length; j++) {\n            intervals[j] = Arrays.stream(parts[j].split(",")).mapToInt(Integer::parseInt).toArray();\n        }\n        System.out.println(Arrays.deepToString(m.merge(intervals)).replace(" ", ""));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 483840 MINUTE)),
(1795000000000000126, '有效的字母异位词', 1, 1, 1000, 128, '给定两个字符串 `s` 和 `t`，编写一个函数来判断 `t` 是否是 `s` 的字母异位词。\n\n字母异位词是指两个字符串中每个字符出现的次数都相同，只是顺序可能不同。\n\n提示：\n- 1 <= s.length, t.length <= 5 * 10^4\n- s 和 t 仅包含小写字母', 'public boolean isAnagram(String s, String t) {\n    // 请在此处编写你的代码\n    return false;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        String s = in.readLine().trim();\n        String u = in.readLine().trim();\n        System.out.println(m.isAnagram(s, u));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 482400 MINUTE)),
(1795000000000000127, '课程表', 2, 2, 1000, 128, '你这个学期必须选修 `numCourses` 门课程，记为 `0` 到 `numCourses - 1`。\n\n在选修某些课程之前需要一些先修课程，先修课程按数组 `prerequisites` 给出，其中 `prerequisites[i] = [a, b]` 表示如果要学习课程 `a` 则必须先学习课程 `b`。\n\n请你判断是否可能完成所有课程的学习，可以返回 `true`，否则返回 `false`。\n\n提示：\n- 1 <= numCourses <= 2000\n- 1 <= prerequisites.length <= 5000\n- prerequisites 中的所有课程对互不相同', 'public boolean canFinish(int numCourses, int[][] prerequisites) {\n    // 请在此处编写你的代码\n    return false;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int n = Integer.parseInt(in.readLine().trim());\n        String[] parts = in.readLine().trim().split(";");\n        int[][] pre = new int[parts.length][];\n        for (int j = 0; j < parts.length; j++) {\n            pre[j] = Arrays.stream(parts[j].split(",")).mapToInt(Integer::parseInt).toArray();\n        }\n        System.out.println(m.canFinish(n, pre));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 480960 MINUTE)),
(1795000000000000128, '数组中的第 K 个最大元素', 2, 2, 1000, 128, '给定整数数组 `nums` 和整数 `k`，请返回数组中第 `k` 个最大的元素。\n\n请注意，你需要找的是数组排序后的第 `k` 个最大的元素，而不是第 `k` 个不同的元素。\n\n提示：\n- 1 <= k <= nums.length <= 10^5\n- -10^4 <= nums[i] <= 10^4\n- 进阶：设计并实现时间复杂度为 O(n) 的算法', 'public int findKthLargest(int[] nums, int k) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        int k = Integer.parseInt(in.readLine().trim());\n        System.out.println(m.findKthLargest(nums, k));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 479520 MINUTE)),
(1795000000000000129, '最小路径和', 2, 2, 1000, 128, '给定一个包含非负整数的 `m x n` 网格 `grid`，请找出一条从左上角到右下角的路径，使得路径上的数字总和最小。\n\n说明：每次只能向下或者向右移动一步。\n\n提示：\n- 1 <= m, n <= 200\n- 0 <= grid[i][j] <= 200', 'public int minPathSum(int[][] grid) {\n    // 请在此处编写你的代码\n    return 0;\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int rows = Integer.parseInt(in.readLine().trim());\n        int[][] grid = new int[rows][];\n        for (int j = 0; j < rows; j++) {\n            grid[j] = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        }\n        System.out.println(m.minPathSum(grid));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 478080 MINUTE)),
(1795000000000000130, '滑动窗口最大值', 3, 1, 1000, 128, '给你一个整数数组 `nums`，有一个大小为 `k` 的滑动窗口从数组的最左侧移动到数组的最右侧，你只可以看到在滑动窗口内的 `k` 个数字，滑动窗口每次只向右移动一位。\n\n返回每个窗口中的最大值组成的数组。\n\n提示：\n- 1 <= nums.length <= 10^5\n- -10^4 <= nums[i] <= 10^4\n- 1 <= k <= nums.length', 'public int[] maxSlidingWindow(int[] nums, int k) {\n    // 请在此处编写你的代码\n    return new int[0];\n}', 'public static void main(String[] args) throws IOException {\n    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n    int t = Integer.parseInt(in.readLine().trim());\n    Main m = new Main();\n    for (int i = 0; i < t; i++) {\n        int[] nums = Arrays.stream(in.readLine().trim().split(",")).mapToInt(Integer::parseInt).toArray();\n        int k = Integer.parseInt(in.readLine().trim());\n        System.out.println(Arrays.toString(m.maxSlidingWindow(nums, k)).replace(" ", ""));\n    }\n}', 1, DATE_SUB(NOW(), INTERVAL 476640 MINUTE));
