(1820000000000000001, 1700000000000000001, 1795000000000000113, NULL, 0, 'public int minDistance(String a, String b) {\n    int n = Math.min(a.length(), b.length());\n    int diff = Math.abs(a.length() - b.length());\n    for (int i = 0; i < n; i++) {\n        if (a.charAt(i) != b.charAt(i)) diff++;\n    }\n    return diff;\n}', 0, '', 240, 2, 4, 5, 199, 70, '4', '01111', '[{"caseId":70,"pass":false,"output":"4"},{"caseId":71,"pass":true},{"caseId":72,"pass":true},{"caseId":73,"pass":true},{"caseId":74,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 421291 MINUTE)),
(1820000000000000002, 1700000000000000001, 1795000000000000113, NULL, 0, 'public int minDistance(String a, String b) {\n    int n = Math.min(a.length(), b.length());\n    int diff = Math.abs(a.length() - b.length());\n    for (int i = 0; i < n; i++) {\n        if (a.charAt(i) != b.charAt(i)) diff++;\n    }\n    return diff;\n}', 0, '', 240, 2, 4, 5, 264, 70, '4', '01111', '[{"caseId":70,"pass":false,"output":"4"},{"caseId":71,"pass":true},{"caseId":72,"pass":true},{"caseId":73,"pass":true},{"caseId":74,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 421281 MINUTE)),
(1820000000000000003, 1700000000000000002, 1795000000000000108, NULL, 0, 'public int lengthOfLongestSubstring(String s) {\n    int[] last = new int[128];\n    Arrays.fill(last, -1);\n    int best = 0, left = 0;\n    for (int i = 0; i < s.length(); i++) {\n        char c = s.charAt(i);\n        left = Math.max(left, last[c] + 1);\n        last[c] = i;\n        best = Math.max(best, i - left + 1);\n    }\n    return best;\n}', 1, '', 200, 1, 7, 7, 270, NULL, NULL, '1111111', '[{"caseId":43,"pass":true},{"caseId":44,"pass":true},{"caseId":45,"pass":true},{"caseId":46,"pass":true},{"caseId":47,"pass":true},{"caseId":48,"pass":true},{"caseId":49,"pass":true}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 417558 MINUTE)),
(1820000000000000004, 1700000000000000001, 1795000000000000108, NULL, 0, 'public int lengthOfLongestSubstring(String s) {\n    int[] last = new int[128];\n    Arrays.fill(last, -1);\n    int best = 0, left = 0;\n    for (int i = 0; i < s.length(); i++) {\n        char c = s.charAt(i);\n        left = Math.max(left, last[c] + 1);\n        last[c] = i;\n        best = Math.max(best, i - left + 1);\n    }\n    return best;\n}', 1, '', 200, 1, 7, 7, 208, NULL, NULL, '1111111', '[{"caseId":43,"pass":true},{"caseId":44,"pass":true},{"caseId":45,"pass":true},{"caseId":46,"pass":true},{"caseId":47,"pass":true},{"caseId":48,"pass":true},{"caseId":49,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 417239 MINUTE)),
(1820000000000000005, 1700000000000000002, 1795000000000000126, NULL, 0, 'public boolean isAnagram(String s, String t) {\n    if (s.length() != t.length()) return false;\n    int[] count = new int[26];\n    for (int i = 0; i < s.length(); i++) {\n        count[s.charAt(i) - ''a'']++;\n        count[t.charAt(i) - ''a'']--;\n    }\n    for (int c : count) {\n        if (c != 0) return false;\n    }\n    return true;\n}', 1, '', 100, 1, 6, 6, 216, NULL, NULL, '111111', '[{"caseId":146,"pass":true},{"caseId":147,"pass":true},{"caseId":148,"pass":true},{"caseId":149,"pass":true},{"caseId":150,"pass":true},{"caseId":151,"pass":true}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 415201 MINUTE)),
(1820000000000000006, 1700000000000000003, 2102360449353351170, NULL, 0, 'public int numIslands(char[][] grid) {\n    int count = 0;\n    for (int i = 0; i < grid.length; i++) {\n        for (int j = 0; j < grid[i].length; j++) {\n            if (grid[i][j] == ''1'') {\n                count++;\n                sink(grid, i, j);\n            }\n        }\n    }\n    return count;\n}\n\nprivate void sink(char[][] g, int i, int j) {\n    if (i < 0 || j < 0 || i >= g.length || j >= g[i].length || g[i][j] != ''1'') return;\n    g[i][j] = ''0'';\n    sink(g, i + 1, j);\n    sink(g, i - 1, j);\n    sink(g, i, j + 1);\n    sink(g, i, j - 1);\n}', 1, '', 200, 1, 6, 6, 259, NULL, NULL, '111111', '[{"caseId":37,"pass":true},{"caseId":38,"pass":true},{"caseId":39,"pass":true},{"caseId":40,"pass":true},{"caseId":41,"pass":true},{"caseId":42,"pass":true}]', 1700000000000000003, DATE_SUB(NOW(), INTERVAL 415002 MINUTE)),
(1820000000000000007, 1700000000000000001, 1796119683661783042, NULL, 0, 'public boolean isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) return false;\n    int half = 0;\n    while (x > half) {\n        half = half * 10 + x % 10;\n        x /= 10;\n    }\n    return x == half || x == half / 10;\n}', 1, '', 100, 1, 7, 7, 210, NULL, NULL, '1111111', '[{"caseId":14,"pass":true},{"caseId":15,"pass":true},{"caseId":16,"pass":true},{"caseId":17,"pass":true},{"caseId":18,"pass":true},{"caseId":19,"pass":true},{"caseId":20,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 410546 MINUTE)),
(1820000000000000008, 1700000000000000004, 1795000000000000116, NULL, 0, 'public int[] merge(int[] nums1, int[] nums2) {\n    int[] r = new int[nums1.length + nums2.length];\n    int i = 0, j = 0, k = 0;\n    while (i < nums1.length && j < nums2.length) {\n        r[k++] = nums1[i] <= nums2[j] ? nums1[i++] : nums2[j++];\n    }\n    while (i < nums1.length) r[k++] = nums1[i++];\n    return r;\n}', 0, '', 33, 2, 2, 6, 247, 85, '[1,2,2,3,0,0]', '011000', '[{"caseId":85,"pass":false,"output":"[1,2,2,3,0,0]"},{"caseId":86,"pass":true},{"caseId":87,"pass":true},{"caseId":88,"pass":false,"output":"[1,1,1,0,0]"},{"caseId":89,"pass":false,"output":"[-5,-3,0,7,0,0,0]"},{"caseId":90,"pass":false,"output":"[1,2,0,0,0]"}]', 1700000000000000004, DATE_SUB(NOW(), INTERVAL 399447 MINUTE)),
(1820000000000000009, 1700000000000000004, 1795000000000000116, NULL, 0, 'public int[] merge(int[] nums1, int[] nums2) {\n    int[] r = new int[nums1.length + nums2.length];\n    int i = 0, j = 0, k = 0;\n    while (i < nums1.length && j < nums2.length) {\n        r[k++] = nums1[i] <= nums2[j] ? nums1[i++] : nums2[j++];\n    }\n    while (i < nums1.length) r[k++] = nums1[i++];\n    while (j < nums2.length) r[k++] = nums2[j++];\n    return r;\n}', 1, '', 100, 1, 6, 6, 209, NULL, NULL, '111111', '[{"caseId":85,"pass":true},{"caseId":86,"pass":true},{"caseId":87,"pass":true},{"caseId":88,"pass":true},{"caseId":89,"pass":true},{"caseId":90,"pass":true}]', 1700000000000000004, DATE_SUB(NOW(), INTERVAL 399425 MINUTE)),
