(1820000000000000017, 1700000000000000003, 1795000000000000106, NULL, 0, 'public int search(int[] nums, int target) {\n    int lo = 0, hi = nums.length - 1;\n    while (lo <= hi) {\n        int mid = (lo + hi) >>> 1;\n        if (nums[mid] == target) return mid;\n        if (nums[mid] < target) lo = mid + 1; else hi = mid - 1;\n    }\n    return -1;\n}', 1, '', 100, 1, 5, 5, 213, NULL, NULL, '11111', '[{"caseId":32,"pass":true},{"caseId":33,"pass":true},{"caseId":34,"pass":true},{"caseId":35,"pass":true},{"caseId":36,"pass":true}]', 1700000000000000003, DATE_SUB(NOW(), INTERVAL 328484 MINUTE)),
