(1820000000000000070, 1700000000000000010, 1794933791345602562, NULL, 0, 'public int[] twoSum(int[] nums, int target) {\n    Map<Integer, Integer> seen = new HashMap<>();\n    for (int i = 0; i < nums.length; i++) {\n        Integer j = seen.get(target - nums[i]);\n        if (j != null) {\n            return new int[]{j, i};\n        }\n        seen.put(nums[i], i);\n    }\n    return new int[0];\n}', 1, '', 100, 1, 5, 5, 301, NULL, NULL, '11111', '[{"caseId":1,"pass":true},{"caseId":2,"pass":true},{"caseId":3,"pass":true},{"caseId":4,"pass":true},{"caseId":5,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 175001 MINUTE)),
