(1820000000000000072, 1700000000000000012, 1795000000000000110, NULL, 0, 'public int coinChange(int[] coins, int amount) {\n    if (amount == 0) return 0;\n    int best = -1;\n    for (int c : coins) {\n        if (c > amount) continue;\n        int sub = coinChange(coins, amount - c);\n        if (sub >= 0 && (best < 0 || sub + 1 < best)) best = sub + 1;\n    }\n    return best;\n}', 0, '程序执行时间超过限制（1000 ms）', 0, 3, 0, 5, 1513, NULL, NULL, '-----', '[{"caseId":55},{"caseId":56},{"caseId":57},{"caseId":58},{"caseId":59}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 169018 MINUTE)),
(1820000000000000073, 1700000000000000012, 1795000000000000110, NULL, 0, 'public int coinChange(int[] coins, int amount) {\n    int[] dp = new int[amount + 1];\n    Arrays.fill(dp, amount + 1);\n    dp[0] = 0;\n    for (int i = 1; i <= amount; i++) {\n        for (int c : coins) {\n            if (c <= i) dp[i] = Math.min(dp[i], dp[i - c] + 1);\n        }\n    }\n    return dp[amount] > amount ? -1 : dp[amount];\n}', 1, '', 200, 1, 5, 5, 314, NULL, NULL, '11111', '[{"caseId":55,"pass":true},{"caseId":56,"pass":true},{"caseId":57,"pass":true},{"caseId":58,"pass":true},{"caseId":59,"pass":true}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 168998 MINUTE)),
(1820000000000000074, 1700000000000000012, 1795000000000000112, NULL, 0, 'public int trap(int[] h) {\n    int max = 0, water = 0;\n    for (int v : h) max = Math.max(max, v);\n    for (int v : h) water += max - v;\n    return water;\n}', 0, '', 120, 2, 2, 5, 264, 65, '22', '00101', '[{"caseId":65,"pass":false,"output":"22"},{"caseId":66,"pass":false,"output":"14"},{"caseId":67,"pass":true},{"caseId":68,"pass":false,"output":"8"},{"caseId":69,"pass":true}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 165520 MINUTE)),
(1820000000000000075, 1700000000000000012, 1795000000000000112, NULL, 0, 'public int trap(int[] h) {\n    int l = 0, r = h.length - 1, lm = 0, rm = 0, water = 0;\n    while (l < r) {\n        if (h[l] < h[r]) {\n            lm = Math.max(lm, h[l]);\n            water += lm - h[l++];\n        } else {\n            rm = Math.max(rm, h[r]);\n            water += rm - h[r--];\n        }\n    }\n    return water;\n}', 1, '', 300, 1, 5, 5, 263, NULL, NULL, '11111', '[{"caseId":65,"pass":true},{"caseId":66,"pass":true},{"caseId":67,"pass":true},{"caseId":68,"pass":true},{"caseId":69,"pass":true}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 165501 MINUTE)),
