(1820000000000000080, 1700000000000000002, 2102360449353351170, NULL, 0, 'public int numIslands(char[][] grid) {\n    int count = 0;\n    for (int i = 0; i < grid.length; i++) {\n        for (int j = 0; j < grid[i].length; j++) {\n            if (grid[i][j] == ''1'') {\n                count++;\n                sink(grid, i, j);\n            }\n        }\n    }\n    return count;\n}\n\nprivate void sink(char[][] g, int i, int j) {\n    if (i >= g.length || j >= g[i].length || g[i][j] != ''1'') return;\n    g[i][j] = ''0'';\n    sink(g, i + 1, j);\n    sink(g, i, j + 1);\n}', 0, '', 167, 2, 5, 6, 261, 42, '2', '111110', '[{"caseId":37,"pass":true},{"caseId":38,"pass":true},{"caseId":39,"pass":true},{"caseId":40,"pass":true},{"caseId":41,"pass":true},{"caseId":42,"pass":false,"output":"2"}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 146354 MINUTE));
