(1820000000000000086, 1700000000000000012, 1795000000000000114, NULL, 0, 'public int longestValidParentheses(String s) {\n    Deque<Integer> stack = new ArrayDeque<>();\n    stack.push(-1);\n    int best = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s.charAt(i) == ''('') {\n            stack.push(i);\n        } else {\n            stack.pop();\n            if (stack.isEmpty()) stack.push(i);\n            else best = Math.max(best, i - stack.peek());\n        }\n    }\n    return best;\n}', 1, '', 300, 1, 5, 5, 260, NULL, NULL, '11111', '[{"caseId":75,"pass":true},{"caseId":76,"pass":true},{"caseId":77,"pass":true},{"caseId":78,"pass":true},{"caseId":79,"pass":true}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 141513 MINUTE)),
