(1820000000000000090, 1700000000000000016, 1795000000000000115, NULL, 0, 'public int totalNQueens(int n) {\n    return place(n, 0, 0, 0);\n}\n\nprivate int place(int n, int row, int cols, int d1) {\n    if (row == n) return 1;\n    int count = 0;\n    int free = ~(cols | d1) & ((1 << n) - 1);\n    while (free != 0) {\n        int bit = free & -free;\n        free -= bit;\n        count += place(n, row + 1, cols | bit, (d1 | bit) << 1);\n    }\n    return count;\n}', 0, '', 60, 2, 1, 5, 310, 80, '7', '01000', '[{"caseId":80,"pass":false,"output":"7"},{"caseId":81,"pass":true},{"caseId":82,"pass":false,"output":"23"},{"caseId":83,"pass":false,"output":"83"},{"caseId":84,"pass":false,"output":"2113"}]', 1700000000000000016, DATE_SUB(NOW(), INTERVAL 126570 MINUTE)),
