(1820000000000000103, 1700000000000000003, 1795000000000000110, NULL, 0, 'public int coinChange(int[] coins, int amount) {\n    int[] dp = new int[amount + 1];\n    Arrays.fill(dp, amount + 1);\n    dp[0] = 0;\n    for (int i = 1; i <= amount; i++) {\n        for (int c : coins) {\n            if (c <= i) dp[i] = Math.min(dp[i], dp[i - c] + 1);\n        }\n    }\n    return dp[amount] > amount ? -1 : dp[amount];\n}', 1, '', 200, 1, 5, 5, 221, NULL, NULL, '11111', '[{"caseId":55,"pass":true},{"caseId":56,"pass":true},{"caseId":57,"pass":true},{"caseId":58,"pass":true},{"caseId":59,"pass":true}]', 1700000000000000003, DATE_SUB(NOW(), INTERVAL 104018 MINUTE)),
