(1820000000000000121, 1700000000000000007, 1795000000000000118, NULL, 0, 'public String reverseWords(String s) {\n    String[] words = s.split(" ");\n    StringBuilder sb = new StringBuilder();\n    for (int i = words.length - 1; i >= 0; i--) {\n        sb.append(words[i]);\n        if (i > 0) sb.append('' '');\n    }\n    return sb.toString();\n}', 0, '', 133, 2, 4, 6, 292, 99, 'example   good a', '110101', '[{"caseId":97,"pass":true},{"caseId":98,"pass":true},{"caseId":99,"pass":false,"output":"example   good a"},{"caseId":100,"pass":true},{"caseId":101,"pass":false,"output":"Alice  Loves    Bob"},{"caseId":102,"pass":true}]', 1700000000000000007, DATE_SUB(NOW(), INTERVAL 59843 MINUTE)),
