(1820000000000000123, 1700000000000000019, 2102360449353351170, NULL, 0, 'public int numIslands(char[][] grid) {\n    int count = 0;\n    for (int i = 0; i < grid.length; i++) {\n        for (int j = 0; j < grid[i].length; j++) {\n            if (grid[i][j] == ''1'') {\n                count++;\n                sink(grid, i, j);\n            }\n        }\n    }\n    return count;\n}\n\nprivate void sink(char[][] g, int i, int j) {\n    if (i < 0 || j < 0 || i >= g.length || j >= g[i].length || g[i][j] != ''1'') return;\n    g[i][j] = ''0'';\n    sink(g, i + 1, j);\n    sink(g, i - 1, j);\n    sink(g, i, j + 1);\n    sink(g, i, j - 1);\n}', 1, '', 200, 1, 6, 6, 308, NULL, NULL, '111111', '[{"caseId":37,"pass":true},{"caseId":38,"pass":true},{"caseId":39,"pass":true},{"caseId":40,"pass":true},{"caseId":41,"pass":true},{"caseId":42,"pass":true}]', 1700000000000000019, DATE_SUB(NOW(), INTERVAL 58136 MINUTE)),
(1820000000000000124, 1700000000000000017, 1795000000000000116, NULL, 0, 'public int[] merge(int[] nums1, int[] nums2) {\n    int[] r = new int[nums1.length + nums2.length];\n    int i = 0, j = 0, k = 0;\n    while (i < nums1.length && j < nums2.length) {\n        r[k++] = nums1[i] <= nums2[j] ? nums1[i++] : nums2[j++];\n    }\n    while (i < nums1.length) r[k++] = nums1[i++];\n    while (j < nums2.length) r[k++] = nums2[j++];\n    return r;\n}', 1, '', 100, 1, 6, 6, 230, NULL, NULL, '111111', '[{"caseId":85,"pass":true},{"caseId":86,"pass":true},{"caseId":87,"pass":true},{"caseId":88,"pass":true},{"caseId":89,"pass":true},{"caseId":90,"pass":true}]', 1700000000000000017, DATE_SUB(NOW(), INTERVAL 57799 MINUTE)),
(1820000000000000125, 1700000000000000002, 1795000000000000113, NULL, 0, 'public int minDistance(String a, String b) {\n    int[][] dp = new int[a.length() + 1][b.length() + 1];\n    for (int i = 0; i <= a.length(); i++) dp[i][0] = i;\n    for (int j = 0; j <= b.length(); j++) dp[0][j] = j;\n    for (int i = 1; i <= a.length(); i++) {\n        for (int j = 1; j <= b.length(); j++) {\n            int same = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;\n            dp[i][j] = Math.min(dp[i - 1][j - 1] + same, Math.min(dp[i - 1][j], dp[i][j - 1]) + 1);\n        }\n    }\n    return dp[a.length()][b.length()];\n}', 1, '', 300, 1, 5, 5, 208, NULL, NULL, '11111', '[{"caseId":70,"pass":true},{"caseId":71,"pass":true},{"caseId":72,"pass":true},{"caseId":73,"pass":true},{"caseId":74,"pass":true}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 57532 MINUTE)),
