(1820000000000000129, 1700000000000000018, 1795000000000000106, NULL, 0, 'public int search(int[] nums, int target) {\n    int lo = 0, hi = nums.length - 1;\n    while (lo <= hi) {\n        int mid = (lo + hi) >>> 1;\n        if (nums[mid] == target) return mid;\n        if (nums[mid] < target) lo = mid + 1; else hi = mid - 1;\n    }\n    return -1;\n}', 1, '', 100, 1, 5, 5, 230, NULL, NULL, '11111', '[{"caseId":32,"pass":true},{"caseId":33,"pass":true},{"caseId":34,"pass":true},{"caseId":35,"pass":true},{"caseId":36,"pass":true}]', 1700000000000000018, DATE_SUB(NOW(), INTERVAL 53277 MINUTE)),
(1820000000000000130, 1700000000000000014, 1795000000000000113, NULL, 0, 'public int minDistance(String a, String b) {\n    int n = Math.min(a.length(), b.length());\n    int diff = Math.abs(a.length() - b.length());\n    for (int i = 0; i < n; i++) {\n        if (a.charAt(i) != b.charAt(i)) diff++;\n    }\n    return diff;\n}', 0, '', 240, 2, 4, 5, 206, 70, '4', '01111', '[{"caseId":70,"pass":false,"output":"4"},{"caseId":71,"pass":true},{"caseId":72,"pass":true},{"caseId":73,"pass":true},{"caseId":74,"pass":true}]', 1700000000000000014, DATE_SUB(NOW(), INTERVAL 43709 MINUTE)),
