(1820000000000000141, 1700000000000000012, 1794900876543210003, NULL, 0, 'public boolean isValid(String s) {\n    Deque<Character> stack = new ArrayDeque<>();\n    for (char c : s.toCharArray()) {\n        if (c == ''('') stack.push('')'');\n        else if (c == ''['') stack.push('']'');\n        else if (c == ''{'') stack.push(''}'');\n        else if (stack.isEmpty() || stack.pop() != c) return false;\n    }\n    return stack.isEmpty();\n}', 1, '', 100, 1, 8, 8, 216, NULL, NULL, '11111111', '[{"caseId":6,"pass":true},{"caseId":7,"pass":true},{"caseId":8,"pass":true},{"caseId":9,"pass":true},{"caseId":10,"pass":true},{"caseId":11,"pass":true},{"caseId":12,"pass":true},{"caseId":13,"pass":true}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 41851 MINUTE)),
