(1820000000000000183, 1700000000000000010, 1795000000000000114, NULL, 0, 'public int longestValidParentheses(String s) {\n    Deque<Integer> stack = new ArrayDeque<>();\n    stack.push(-1);\n    int best = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s.charAt(i) == ''('') {\n            stack.push(i);\n        } else {\n            stack.pop();\n            if (stack.isEmpty()) stack.push(i);\n            else best = Math.max(best, i - stack.peek());\n        }\n    }\n    return best;\n}', 1, '', 300, 1, 5, 5, 288, NULL, NULL, '11111', '[{"caseId":75,"pass":true},{"caseId":76,"pass":true},{"caseId":77,"pass":true},{"caseId":78,"pass":true},{"caseId":79,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 36980 MINUTE)),
(1820000000000000184, 1700000000000000014, 1795000000000000130, NULL, 0, 'public int[] maxSlidingWindow(int[] nums, int k) {\n    int[] r = new int[nums.length - k + 1];\n    Deque<Integer> dq = new ArrayDeque<>();\n    for (int i = 0; i < nums.length; i++) {\n        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();\n        dq.offerLast(i);\n        if (i >= k - 1) r[i - k + 1] = nums[dq.peekFirst()];\n    }\n    return r;\n}', 0, '', 171, 2, 4, 7, 359, 174, '[3,3,3,5]', '1111000', '[{"caseId":170,"pass":true},{"caseId":171,"pass":true},{"caseId":172,"pass":true},{"caseId":173,"pass":true},{"caseId":174,"pass":false,"output":"[3,3,3,5]"},{"caseId":175,"pass":false,"output":"[7,7]"},{"caseId":176,"pass":false,"output":"[9,9,9,9,9]"}]', 1700000000000000014, DATE_SUB(NOW(), INTERVAL 36790 MINUTE)),
