(1820000000000000196, 1700000000000000001, 1796119683661783042, NULL, 0, 'public boolean isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) return false;\n    int half = 0;\n    while (x > half) {\n        half = half * 10 + x % 10;\n        x /= 10;\n    }\n    return x == half || x == half / 10;\n}', 1, '', 100, 1, 7, 7, 293, NULL, NULL, '1111111', '[{"caseId":14,"pass":true},{"caseId":15,"pass":true},{"caseId":16,"pass":true},{"caseId":17,"pass":true},{"caseId":18,"pass":true},{"caseId":19,"pass":true},{"caseId":20,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 35964 MINUTE)),
