(1820000000000000198, 1700000000000000001, 1795000000000000110, NULL, 0, 'public int coinChange(int[] coins, int amount) {\n    Arrays.sort(coins);\n    int count = 0;\n    for (int i = coins.length - 1; i >= 0; i--) {\n        count += amount / coins[i];\n        amount %= coins[i];\n    }\n    return amount == 0 ? count : -1;\n}', 0, '', 160, 2, 4, 5, 274, 58, '-1', '11101', '[{"caseId":55,"pass":true},{"caseId":56,"pass":true},{"caseId":57,"pass":true},{"caseId":58,"pass":false,"output":"-1"},{"caseId":59,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 35893 MINUTE)),
(1820000000000000199, 1700000000000000001, 1795000000000000110, NULL, 0, 'public int coinChange(int[] coins, int amount) {\n    int[] dp = new int[amount + 1];\n    Arrays.fill(dp, amount + 1);\n    dp[0] = 0;\n    for (int i = 1; i <= amount; i++) {\n        for (int c : coins) {\n            if (c <= i) dp[i] = Math.min(dp[i], dp[i - c] + 1);\n        }\n    }\n    return dp[amount] > amount ? -1 : dp[amount];\n}', 1, '', 200, 1, 5, 5, 244, NULL, NULL, '11111', '[{"caseId":55,"pass":true},{"caseId":56,"pass":true},{"caseId":57,"pass":true},{"caseId":58,"pass":true},{"caseId":59,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 35871 MINUTE)),
