(1820000000000000221, 1700000000000000009, 1794933791345602562, NULL, 0, 'public int[] twoSum(int[] nums, int target) {\n    Map<Integer, Integer> seen = new HashMap<>();\n    for (int i = 0; i < nums.length; i++) {\n        Integer j = seen.get(target - nums[i]);\n        if (j != null) {\n            return new int[]{j, i};\n        }\n        seen.put(nums[i], i);\n    }\n    return new int[0];\n}', 1, '', 100, 1, 5, 5, 278, NULL, NULL, '11111', '[{"caseId":1,"pass":true},{"caseId":2,"pass":true},{"caseId":3,"pass":true},{"caseId":4,"pass":true},{"caseId":5,"pass":true}]', 1700000000000000009, DATE_SUB(NOW(), INTERVAL 33794 MINUTE)),
(1820000000000000222, 1700000000000000004, 2102360449353351170, NULL, 0, 'public int numIslands(char[][] grid) {\n    int count = 0;\n    for (int i = 0; i < grid.length; i++) {\n        for (int j = 0; j < grid[i].length; j++) {\n            if (grid[i][j] == ''1'') {\n                count++;\n                sink(grid, i, j);\n            }\n        }\n    }\n    return count;\n}\n\nprivate void sink(char[][] g, int i, int j) {\n    if (i >= g.length || j >= g[i].length || g[i][j] != ''1'') return;\n    g[i][j] = ''0'';\n    sink(g, i + 1, j);\n    sink(g, i, j + 1);\n}', 1, '', 200, 1, 5, 6, 247, 42, '2', '111110', '[{"caseId":37,"pass":true},{"caseId":38,"pass":true},{"caseId":39,"pass":true},{"caseId":40,"pass":true},{"caseId":41,"pass":true},{"caseId":42,"pass":false,"output":"2"}]', 1700000000000000004, DATE_SUB(NOW(), INTERVAL 33610 MINUTE)),
