(1820000000000000261, 1700000000000000001, 1795000000000000112, NULL, 0, 'public int trap(int[] h) {\n    int l = 0, r = h.length - 1, lm = 0, rm = 0, water = 0;\n    while (l < r) {\n        if (h[l] < h[r]) {\n            lm = Math.max(lm, h[l]);\n            water += lm - h[l++];\n        } else {\n            rm = Math.max(rm, h[r]);\n            water += rm - h[r--];\n        }\n    }\n    return water;\n}', 1, '', 300, 1, 5, 5, 268, NULL, NULL, '11111', '[{"caseId":65,"pass":true},{"caseId":66,"pass":true},{"caseId":67,"pass":true},{"caseId":68,"pass":true},{"caseId":69,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 31409 MINUTE)),
