(1820000000000000275, 1700000000000000015, 1795000000000000114, NULL, 0, 'public int longestValidParentheses(String s) {\n    Deque<Integer> stack = new ArrayDeque<>();\n    stack.push(-1);\n    int best = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s.charAt(i) == ''('') {\n            stack.push(i);\n        } else {\n            stack.pop();\n            if (stack.isEmpty()) stack.push(i);\n            else best = Math.max(best, i - stack.peek());\n        }\n    }\n    return best\n}', 0, 'Solution.java:19: error: '';'' expected\n    return best\n               ^\n1 error\n', 0, 5, 0, 5, 5, NULL, NULL, '-----', '[{"caseId":75},{"caseId":76},{"caseId":77},{"caseId":78},{"caseId":79}]', 1700000000000000015, DATE_SUB(NOW(), INTERVAL 29492 MINUTE)),
(1820000000000000276, 1700000000000000002, 2102360449353351170, NULL, 0, 'public int numIslands(char[][] grid) {\n    int count = 0;\n    for (int i = 0; i < grid.length; i++) {\n        for (int j = 0; j < grid[i].length; j++) {\n            if (grid[i][j] == ''1'') {\n                count++;\n                sink(grid, i, j);\n            }\n        }\n    }\n    return count;\n}\n\nprivate void sink(char[][] g, int i, int j) {\n    if (i < 0 || j < 0 || i >= g.length || j >= g[i].length || g[i][j] != ''1'') return;\n    g[i][j] = ''0'';\n    sink(g, i + 1, j);\n    sink(g, i - 1, j);\n    sink(g, i, j + 1);\n    sink(g, i, j - 1);\n}', 1, '', 200, 1, 6, 6, 317, NULL, NULL, '111111', '[{"caseId":37,"pass":true},{"caseId":38,"pass":true},{"caseId":39,"pass":true},{"caseId":40,"pass":true},{"caseId":41,"pass":true},{"caseId":42,"pass":true}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 29482 MINUTE)),
