(1820000000000000315, 1700000000000000020, 2102360449353351170, NULL, 0, 'public int numIslands(char[][] grid) {\n    int count = 0;\n    for (int i = 0; i < grid.length; i++) {\n        for (int j = 0; j < grid[i].length; j++) {\n            if (grid[i][j] == ''1'') {\n                count++;\n                sink(grid, i, j);\n            }\n        }\n    }\n    return count;\n}\n\nprivate void sink(char[][] g, int i, int j) {\n    if (i < 0 || j < 0 || i >= g.length || j >= g[i].length || g[i][j] != ''1'') return;\n    g[i][j] = ''0'';\n    sink(g, i + 1, j);\n    sink(g, i - 1, j);\n    sink(g, i, j + 1);\n    sink(g, i, j - 1);\n}', 1, '', 200, 1, 6, 6, 298, NULL, NULL, '111111', '[{"caseId":37,"pass":true},{"caseId":38,"pass":true},{"caseId":39,"pass":true},{"caseId":40,"pass":true},{"caseId":41,"pass":true},{"caseId":42,"pass":true}]', 1700000000000000020, DATE_SUB(NOW(), INTERVAL 29118 MINUTE)),
(1820000000000000316, 1700000000000000006, 1794900876543210003, NULL, 0, 'public boolean isValid(String s) {\n    int a = 0, b = 0, c = 0;\n    for (char ch : s.toCharArray()) {\n        if (ch == ''('') a++;\n        else if (ch == '')'') a--;\n        else if (ch == ''['') b++;\n        else if (ch == '']'') b--;\n        else if (ch == ''{'') c++;\n        else c--;\n        if (a < 0 || b < 0 || c < 0) return false;\n    }\n    return a == 0 && b == 0 && c == 0;\n}', 0, '', 88, 2, 7, 8, 235, 9, 'true', '11101111', '[{"caseId":6,"pass":true},{"caseId":7,"pass":true},{"caseId":8,"pass":true},{"caseId":9,"pass":false,"output":"true"},{"caseId":10,"pass":true},{"caseId":11,"pass":true},{"caseId":12,"pass":true},{"caseId":13,"pass":true}]', 1700000000000000006, DATE_SUB(NOW(), INTERVAL 28999 MINUTE)),
