(1820000000000000325, 1700000000000000001, 1795000000000000113, NULL, 0, 'public int minDistance(String a, String b) {\n    int[][] dp = new int[a.length() + 1][b.length() + 1];\n    for (int i = 0; i <= a.length(); i++) dp[i][0] = i;\n    for (int j = 0; j <= b.length(); j++) dp[0][j] = j;\n    for (int i = 1; i <= a.length(); i++) {\n        for (int j = 1; j <= b.length(); j++) {\n            int same = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;\n            dp[i][j] = Math.min(dp[i - 1][j - 1] + same, Math.min(dp[i - 1][j], dp[i][j - 1]) + 1);\n        }\n    }\n    return dp[a.length()][b.length()];\n}', 1, '', 300, 1, 5, 5, 246, NULL, NULL, '11111', '[{"caseId":70,"pass":true},{"caseId":71,"pass":true},{"caseId":72,"pass":true},{"caseId":73,"pass":true},{"caseId":74,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 28448 MINUTE)),
