(1820000000000000340, 1700000000000000009, 1795000000000000109, NULL, 0, 'public int lengthOfLIS(int[] nums) {\n    int[] tails = new int[nums.length];\n    int size = 0;\n    for (int v : nums) {\n        int lo = 0, hi = size;\n        while (lo < hi) {\n            int mid = (lo + hi) >>> 1;\n            if (tails[mid] < v) lo = mid + 1; else hi = mid;\n        }\n        tails[lo] = v;\n        if (lo == size) size++;\n    }\n    return size;\n}', 1, '', 200, 1, 5, 5, 251, NULL, NULL, '11111', '[{"caseId":50,"pass":true},{"caseId":51,"pass":true},{"caseId":52,"pass":true},{"caseId":53,"pass":true},{"caseId":54,"pass":true}]', 1700000000000000009, DATE_SUB(NOW(), INTERVAL 28142 MINUTE)),
