(1820000000000000343, 1700000000000000010, 1795000000000000110, NULL, 0, 'public int coinChange(int[] coins, int amount) {\n    Arrays.sort(coins);\n    int count = 0;\n    for (int i = coins.length - 1; i >= 0; i--) {\n        count += amount / coins[i];\n        amount %= coins[i];\n    }\n    return amount == 0 ? count : -1;\n}', 0, '', 160, 2, 4, 5, 239, 58, '-1', '11101', '[{"caseId":55,"pass":true},{"caseId":56,"pass":true},{"caseId":57,"pass":true},{"caseId":58,"pass":false,"output":"-1"},{"caseId":59,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 27779 MINUTE)),
(1820000000000000344, 1700000000000000010, 1795000000000000110, NULL, 0, 'public int coinChange(int[] coins, int amount) {\n    int[] dp = new int[amount + 1];\n    Arrays.fill(dp, amount + 1);\n    dp[0] = 0;\n    for (int i = 1; i <= amount; i++) {\n        for (int c : coins) {\n            if (c <= i) dp[i] = Math.min(dp[i], dp[i - c] + 1);\n        }\n    }\n    return dp[amount] > amount ? -1 : dp[amount];\n}', 1, '', 200, 1, 5, 5, 285, NULL, NULL, '11111', '[{"caseId":55,"pass":true},{"caseId":56,"pass":true},{"caseId":57,"pass":true},{"caseId":58,"pass":true},{"caseId":59,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 27760 MINUTE)),
(1820000000000000345, 1700000000000000002, 1795000000000000126, NULL, 0, 'public boolean isAnagram(String s, String t) {\n    if (s.length() != t.length()) return false;\n    int[] count = new int[26];\n    for (int i = 0; i < s.length(); i++) {\n        count[s.charAt(i) - ''a'']++;\n        count[t.charAt(i) - ''a'']--;\n    }\n    for (int c : count) {\n        if (c != 0) return false;\n    }\n    return true;\n}', 1, '', 100, 1, 6, 6, 270, NULL, NULL, '111111', '[{"caseId":146,"pass":true},{"caseId":147,"pass":true},{"caseId":148,"pass":true},{"caseId":149,"pass":true},{"caseId":150,"pass":true},{"caseId":151,"pass":true}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 27669 MINUTE)),
