(1820000000000000365, 1700000000000000010, 1794900876543210003, NULL, 0, 'public boolean isValid(String s) {\n    Deque<Character> stack = new ArrayDeque<>();\n    for (char c : s.toCharArray()) {\n        if (c == ''('') stack.push('')'');\n        else if (c == ''['') stack.push('']'');\n        else if (c == ''{'') stack.push(''}'');\n        else if (stack.isEmpty() || stack.pop() != c) return false;\n    }\n    return stack.isEmpty();\n}', 1, '', 100, 1, 8, 8, 219, NULL, NULL, '11111111', '[{"caseId":6,"pass":true},{"caseId":7,"pass":true},{"caseId":8,"pass":true},{"caseId":9,"pass":true},{"caseId":10,"pass":true},{"caseId":11,"pass":true},{"caseId":12,"pass":true},{"caseId":13,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 25343 MINUTE)),
(1820000000000000366, 1700000000000000006, 1795000000000000115, NULL, 0, 'public int totalNQueens(int n) {\n    return place(n, 0, 0, 0, 0);\n}\n\nprivate int place(int n, int row, int cols, int d1, int d2) {\n    if (row == n) return 1;\n    int count = 0;\n    int free = ~(cols | d1 | d2) & ((1 << n) - 1);\n    while (free != 0) {\n        int bit = free & -free;\n        free -= bit;\n        count += place(n, row + 1, cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1);\n    }\n    return count\n}', 0, 'Solution.java:19: error: '';'' expected\n    return count\n                ^\n1 error\n', 0, 5, 0, 5, 5, NULL, NULL, '-----', '[{"caseId":80},{"caseId":81},{"caseId":82},{"caseId":83},{"caseId":84}]', 1700000000000000006, DATE_SUB(NOW(), INTERVAL 24895 MINUTE)),
