(1820000000000000443, 1700000000000000010, 1795000000000000109, NULL, 0, 'public int lengthOfLIS(int[] nums) {\n    int[] tails = new int[nums.length];\n    int size = 0;\n    for (int v : nums) {\n        int lo = 0, hi = size;\n        while (lo < hi) {\n            int mid = (lo + hi) >>> 1;\n            if (tails[mid] < v) lo = mid + 1; else hi = mid;\n        }\n        tails[lo] = v;\n        if (lo == size) size++;\n    }\n    return size;\n}', 1, '', 200, 1, 5, 5, 302, NULL, NULL, '11111', '[{"caseId":50,"pass":true},{"caseId":51,"pass":true},{"caseId":52,"pass":true},{"caseId":53,"pass":true},{"caseId":54,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 18228 MINUTE)),
(1820000000000000444, 1700000000000000009, 1795000000000000115, NULL, 0, 'public int totalNQueens(int n) {\n    return place(n, 0, 0, 0, 0);\n}\n\nprivate int place(int n, int row, int cols, int d1, int d2) {\n    if (row == n) return 1;\n    int count = 0;\n    int free = ~(cols | d1 | d2) & ((1 << n) - 1);\n    while (free != 0) {\n        int bit = free & -free;\n        free -= bit;\n        count += place(n, row + 1, cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1);\n    }\n    return count\n}', 0, 'Solution.java:19: error: '';'' expected\n    return count\n                ^\n1 error\n', 0, 5, 0, 5, 10, NULL, NULL, '-----', '[{"caseId":80},{"caseId":81},{"caseId":82},{"caseId":83},{"caseId":84}]', 1700000000000000009, DATE_SUB(NOW(), INTERVAL 18037 MINUTE)),
(1820000000000000445, 1700000000000000012, 1796119683661783042, NULL, 0, 'public boolean isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) return false;\n    int half = 0;\n    while (x > half) {\n        half = half * 10 + x % 10;\n        x /= 10;\n    }\n    return x == half || x == half / 10;\n}', 1, '', 100, 1, 7, 7, 258, NULL, NULL, '1111111', '[{"caseId":14,"pass":true},{"caseId":15,"pass":true},{"caseId":16,"pass":true},{"caseId":17,"pass":true},{"caseId":18,"pass":true},{"caseId":19,"pass":true},{"caseId":20,"pass":true}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 18019 MINUTE)),
(1820000000000000446, 1700000000000000002, 1795000000000000106, NULL, 0, 'public int search(int[] nums, int target) {\n    int lo = 0, hi = nums.length - 1;\n    while (lo <= hi) {\n        int mid = (lo + hi) >>> 1;\n        if (nums[mid] == target) return mid;\n        if (nums[mid] < target) lo = mid + 1; else hi = mid - 1;\n    }\n    return -1;\n}', 1, '', 100, 1, 5, 5, 199, NULL, NULL, '11111', '[{"caseId":32,"pass":true},{"caseId":33,"pass":true},{"caseId":34,"pass":true},{"caseId":35,"pass":true},{"caseId":36,"pass":true}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 17832 MINUTE)),
