(1820000000000000449, 1700000000000000006, 1795000000000000108, NULL, 0, 'public int lengthOfLongestSubstring(String s) {\n    int[] last = new int[128];\n    Arrays.fill(last, -1);\n    int best = 0, left = 0;\n    for (int i = 0; i < s.length(); i++) {\n        char c = s.charAt(i);\n        left = Math.max(left, last[c] + 1);\n        last[c] = i;\n        best = Math.max(best, i - left + 1);\n    }\n    return best\n}', 0, 'Solution.java:16: error: '';'' expected\n    return best\n               ^\n1 error\n', 0, 5, 0, 7, 5, NULL, NULL, '-------', '[{"caseId":43},{"caseId":44},{"caseId":45},{"caseId":46},{"caseId":47},{"caseId":48},{"caseId":49}]', 1700000000000000006, DATE_SUB(NOW(), INTERVAL 17628 MINUTE)),
