(1820000000000000479, 1700000000000000010, 1795000000000000114, NULL, 0, 'public int longestValidParentheses(String s) {\n    Deque<Integer> stack = new ArrayDeque<>();\n    stack.push(-1);\n    int best = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s.charAt(i) == ''('') {\n            stack.push(i);\n        } else {\n            stack.pop();\n            if (stack.isEmpty()) stack.push(i);\n            else best = Math.max(best, i - stack.peek());\n        }\n    }\n    return best;\n}', 1, '', 300, 1, 5, 5, 234, NULL, NULL, '11111', '[{"caseId":75,"pass":true},{"caseId":76,"pass":true},{"caseId":77,"pass":true},{"caseId":78,"pass":true},{"caseId":79,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 14835 MINUTE)),
(1820000000000000480, 1700000000000000004, 1794900876543210003, NULL, 0, 'public boolean isValid(String s) {\n    int a = 0, b = 0, c = 0;\n    for (char ch : s.toCharArray()) {\n        if (ch == ''('') a++;\n        else if (ch == '')'') a--;\n        else if (ch == ''['') b++;\n        else if (ch == '']'') b--;\n        else if (ch == ''{'') c++;\n        else c--;\n        if (a < 0 || b < 0 || c < 0) return false;\n    }\n    return a == 0 && b == 0 && c == 0;\n}', 0, '', 88, 2, 7, 8, 237, 9, 'true', '11101111', '[{"caseId":6,"pass":true},{"caseId":7,"pass":true},{"caseId":8,"pass":true},{"caseId":9,"pass":false,"output":"true"},{"caseId":10,"pass":true},{"caseId":11,"pass":true},{"caseId":12,"pass":true},{"caseId":13,"pass":true}]', 1700000000000000004, DATE_SUB(NOW(), INTERVAL 14711 MINUTE));
