(1820000000000000502, 1700000000000000010, 1794933791345602562, NULL, 0, 'public int[] twoSum(int[] nums, int target) {\n    Map<Integer, Integer> seen = new HashMap<>();\n    for (int i = 0; i < nums.length; i++) {\n        Integer j = seen.get(target - nums[i]);\n        if (j != null) {\n            return new int[]{j, i};\n        }\n        seen.put(nums[i], i);\n    }\n    return new int[0];\n}', 1, '', 100, 1, 5, 5, 242, NULL, NULL, '11111', '[{"caseId":1,"pass":true},{"caseId":2,"pass":true},{"caseId":3,"pass":true},{"caseId":4,"pass":true},{"caseId":5,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 13037 MINUTE)),
(1820000000000000503, 1700000000000000011, 1795000000000000130, NULL, 0, 'public int[] maxSlidingWindow(int[] nums, int k) {\n    int[] r = new int[nums.length - k + 1];\n    Deque<Integer> dq = new ArrayDeque<>();\n    for (int i = 0; i < nums.length; i++) {\n        while (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();\n        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();\n        dq.offerLast(i);\n        if (i >= k - 1) r[i - k + 1] = nums[dq.peekFirst()];\n    }\n    return r;\n}', 1, '', 300, 1, 7, 7, 239, NULL, NULL, '1111111', '[{"caseId":170,"pass":true},{"caseId":171,"pass":true},{"caseId":172,"pass":true},{"caseId":173,"pass":true},{"caseId":174,"pass":true},{"caseId":175,"pass":true},{"caseId":176,"pass":true}]', 1700000000000000011, DATE_SUB(NOW(), INTERVAL 13032 MINUTE)),
