(1820000000000000521, 1700000000000000007, 1795000000000000115, NULL, 0, 'public int totalNQueens(int n) {\n    return place(n, 0, 0, 0);\n}\n\nprivate int place(int n, int row, int cols, int d1) {\n    if (row == n) return 1;\n    int count = 0;\n    int free = ~(cols | d1) & ((1 << n) - 1);\n    while (free != 0) {\n        int bit = free & -free;\n        free -= bit;\n        count += place(n, row + 1, cols | bit, (d1 | bit) << 1);\n    }\n    return count;\n}', 0, '', 60, 2, 1, 5, 313, 80, '7', '01000', '[{"caseId":80,"pass":false,"output":"7"},{"caseId":81,"pass":true},{"caseId":82,"pass":false,"output":"23"},{"caseId":83,"pass":false,"output":"83"},{"caseId":84,"pass":false,"output":"2113"}]', 1700000000000000007, DATE_SUB(NOW(), INTERVAL 11397 MINUTE)),
(1820000000000000522, 1700000000000000006, 1795000000000000113, NULL, 0, 'public int minDistance(String a, String b) {\n    int[][] dp = new int[a.length() + 1][b.length() + 1];\n    for (int i = 0; i <= a.length(); i++) dp[i][0] = i;\n    for (int j = 0; j <= b.length(); j++) dp[0][j] = j;\n    for (int i = 1; i <= a.length(); i++) {\n        for (int j = 1; j <= b.length(); j++) {\n            int same = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;\n            dp[i][j] = Math.min(dp[i - 1][j - 1] + same, Math.min(dp[i - 1][j], dp[i][j - 1]) + 1);\n        }\n    }\n    return dp[a.length()][b.length()]\n}', 0, 'Solution.java:16: error: '';'' expected\n    return dp[a.length()][b.length()]\n                                     ^\n1 error\n', 0, 5, 0, 5, 40, NULL, NULL, '-----', '[{"caseId":70},{"caseId":71},{"caseId":72},{"caseId":73},{"caseId":74}]', 1700000000000000006, DATE_SUB(NOW(), INTERVAL 11205 MINUTE)),
