(1820000000000000525, 1700000000000000003, 1795000000000000122, NULL, 0, 'public int maxArea(int[] height) {\n    int l = 0, r = height.length - 1, best = 0;\n    while (l < r) {\n        best = Math.max(best, (r - l) * Math.min(height[l], height[r]));\n        if (height[l] < height[r]) l++; else r--;\n    }\n    return best;\n}', 1, '', 200, 1, 6, 6, 263, NULL, NULL, '111111', '[{"caseId":121,"pass":true},{"caseId":122,"pass":true},{"caseId":123,"pass":true},{"caseId":124,"pass":true},{"caseId":125,"pass":true},{"caseId":126,"pass":true}]', 1700000000000000003, DATE_SUB(NOW(), INTERVAL 10728 MINUTE)),
