(1820000000000000532, 1700000000000000012, 1795000000000000130, NULL, 0, 'public int[] maxSlidingWindow(int[] nums, int k) {\n    int[] r = new int[nums.length - k + 1];\n    Deque<Integer> dq = new ArrayDeque<>();\n    for (int i = 0; i < nums.length; i++) {\n        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();\n        dq.offerLast(i);\n        if (i >= k - 1) r[i - k + 1] = nums[dq.peekFirst()];\n    }\n    return r;\n}', 0, '', 171, 2, 4, 7, 325, 174, '[3,3,3,5]', '1111000', '[{"caseId":170,"pass":true},{"caseId":171,"pass":true},{"caseId":172,"pass":true},{"caseId":173,"pass":true},{"caseId":174,"pass":false,"output":"[3,3,3,5]"},{"caseId":175,"pass":false,"output":"[7,7]"},{"caseId":176,"pass":false,"output":"[9,9,9,9,9]"}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 10427 MINUTE)),
(1820000000000000533, 1700000000000000012, 1795000000000000130, NULL, 0, 'public int[] maxSlidingWindow(int[] nums, int k) {\n    int[] r = new int[nums.length - k + 1];\n    Deque<Integer> dq = new ArrayDeque<>();\n    for (int i = 0; i < nums.length; i++) {\n        while (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();\n        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();\n        dq.offerLast(i);\n        if (i >= k - 1) r[i - k + 1] = nums[dq.peekFirst()];\n    }\n    return r\n}', 0, 'Solution.java:15: error: '';'' expected\n    return r\n            ^\n1 error\n', 0, 5, 0, 7, 5, NULL, NULL, '-------', '[{"caseId":170},{"caseId":171},{"caseId":172},{"caseId":173},{"caseId":174},{"caseId":175},{"caseId":176}]', 1700000000000000012, DATE_SUB(NOW(), INTERVAL 10422 MINUTE)),
