(1820000000000000544, 1700000000000000013, 1794900876543210003, NULL, 0, 'public boolean isValid(String s) {\n    int a = 0, b = 0, c = 0;\n    for (char ch : s.toCharArray()) {\n        if (ch == ''('') a++;\n        else if (ch == '')'') a--;\n        else if (ch == ''['') b++;\n        else if (ch == '']'') b--;\n        else if (ch == ''{'') c++;\n        else c--;\n        if (a < 0 || b < 0 || c < 0) return false;\n    }\n    return a == 0 && b == 0 && c == 0;\n}', 0, '', 88, 2, 7, 8, 214, 9, 'true', '11101111', '[{"caseId":6,"pass":true},{"caseId":7,"pass":true},{"caseId":8,"pass":true},{"caseId":9,"pass":false,"output":"true"},{"caseId":10,"pass":true},{"caseId":11,"pass":true},{"caseId":12,"pass":true},{"caseId":13,"pass":true}]', 1700000000000000013, DATE_SUB(NOW(), INTERVAL 9748 MINUTE)),
(1820000000000000545, 1700000000000000013, 1794900876543210003, NULL, 0, 'public boolean isValid(String s) {\n    Deque<Character> stack = new ArrayDeque<>();\n    for (char c : s.toCharArray()) {\n        if (c == ''('') stack.push('')'');\n        else if (c == ''['') stack.push('']'');\n        else if (c == ''{'') stack.push(''}'');\n        else if (stack.isEmpty() || stack.pop() != c) return false;\n    }\n    return stack.isEmpty();\n}', 1, '', 100, 1, 8, 8, 213, NULL, NULL, '11111111', '[{"caseId":6,"pass":true},{"caseId":7,"pass":true},{"caseId":8,"pass":true},{"caseId":9,"pass":true},{"caseId":10,"pass":true},{"caseId":11,"pass":true},{"caseId":12,"pass":true},{"caseId":13,"pass":true}]', 1700000000000000013, DATE_SUB(NOW(), INTERVAL 9737 MINUTE)),
