(1820000000000000615, 1700000000000000017, 1795000000000000108, NULL, 0, 'public int lengthOfLongestSubstring(String s) {\n    int[] last = new int[128];\n    Arrays.fill(last, -1);\n    int best = 0, left = 0;\n    for (int i = 0; i < s.length(); i++) {\n        char c = s.charAt(i);\n        left = Math.max(left, last[c] + 1);\n        last[c] = i;\n        best = Math.max(best, i - left + 1);\n    }\n    return best;\n}', 1, '', 200, 1, 7, 7, 242, NULL, NULL, '1111111', '[{"caseId":43,"pass":true},{"caseId":44,"pass":true},{"caseId":45,"pass":true},{"caseId":46,"pass":true},{"caseId":47,"pass":true},{"caseId":48,"pass":true},{"caseId":49,"pass":true}]', 1700000000000000017, DATE_SUB(NOW(), INTERVAL 8825 MINUTE)),
(1820000000000000616, 1700000000000000004, 1796119683661783042, NULL, 0, 'public boolean isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) return false;\n    int half = 0;\n    while (x > half) {\n        half = half * 10 + x % 10;\n        x /= 10;\n    }\n    return x == half || x == half / 10;\n}', 1, '', 100, 1, 7, 7, 275, NULL, NULL, '1111111', '[{"caseId":14,"pass":true},{"caseId":15,"pass":true},{"caseId":16,"pass":true},{"caseId":17,"pass":true},{"caseId":18,"pass":true},{"caseId":19,"pass":true},{"caseId":20,"pass":true}]', 1700000000000000004, DATE_SUB(NOW(), INTERVAL 8823 MINUTE)),
