(1820000000000000623, 1700000000000000002, 1795000000000000114, NULL, 0, 'public int longestValidParentheses(String s) {\n    Deque<Integer> stack = new ArrayDeque<>();\n    stack.push(-1);\n    int best = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s.charAt(i) == ''('') {\n            stack.push(i);\n        } else {\n            stack.pop();\n            if (stack.isEmpty()) stack.push(i);\n            else best = Math.max(best, i - stack.peek());\n        }\n    }\n    return best;\n}', 1, '', 300, 1, 5, 5, 258, NULL, NULL, '11111', '[{"caseId":75,"pass":true},{"caseId":76,"pass":true},{"caseId":77,"pass":true},{"caseId":78,"pass":true},{"caseId":79,"pass":true}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 8320 MINUTE)),
(1820000000000000624, 1700000000000000019, 1795000000000000114, NULL, 0, 'public int longestValidParentheses(String s) {\n    int open = 0, pairs = 0;\n    for (char c : s.toCharArray()) {\n        if (c == ''('') open++;\n        else if (open > 0) { open--; pairs++; }\n    }\n    return pairs * 2;\n}', 0, '', 240, 2, 4, 5, 235, 79, '4', '11110', '[{"caseId":75,"pass":true},{"caseId":76,"pass":true},{"caseId":77,"pass":true},{"caseId":78,"pass":true},{"caseId":79,"pass":false,"output":"4"}]', 1700000000000000019, DATE_SUB(NOW(), INTERVAL 8213 MINUTE)),
(1820000000000000625, 1700000000000000018, 1795000000000000130, NULL, 0, 'public int[] maxSlidingWindow(int[] nums, int k) {\n    int[] r = new int[nums.length - k];\n    for (int i = 0; i + k <= nums.length; i++) {\n        int max = nums[i];\n        for (int j = i; j < i + k; j++) max = Math.max(max, nums[j]);\n        r[i] = max;\n    }\n    return r;\n}', 0, 'Exception in thread "main" java.lang.ArrayIndexOutOfBoundsException: Index 5 out of bounds for length 5\n	at Solution.maxSlidingWindow(Solution.java:11)\n	at Solution.main(Solution.java:23)', 0, 6, 0, 7, 265, 170, NULL, '0------', '[{"caseId":170,"pass":false},{"caseId":171},{"caseId":172},{"caseId":173},{"caseId":174},{"caseId":175},{"caseId":176}]', 1700000000000000018, DATE_SUB(NOW(), INTERVAL 8100 MINUTE)),
(1820000000000000626, 1700000000000000018, 1795000000000000130, NULL, 0, 'public int[] maxSlidingWindow(int[] nums, int k) {\n    int[] r = new int[nums.length - k + 1];\n    Deque<Integer> dq = new ArrayDeque<>();\n    for (int i = 0; i < nums.length; i++) {\n        while (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();\n        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();\n        dq.offerLast(i);\n        if (i >= k - 1) r[i - k + 1] = nums[dq.peekFirst()];\n    }\n    return r;\n}', 1, '', 300, 1, 7, 7, 228, NULL, NULL, '1111111', '[{"caseId":170,"pass":true},{"caseId":171,"pass":true},{"caseId":172,"pass":true},{"caseId":173,"pass":true},{"caseId":174,"pass":true},{"caseId":175,"pass":true},{"caseId":176,"pass":true}]', 1700000000000000018, DATE_SUB(NOW(), INTERVAL 8085 MINUTE)),
(1820000000000000627, 1700000000000000018, 2102360449353351170, NULL, 0, 'public int numIslands(char[][] grid) {\n    int count = 0;\n    for (int i = 0; i < grid.length; i++) {\n        for (int j = 0; j < grid[i].length; j++) {\n            if (grid[i][j] == ''1'') {\n                count++;\n                sink(grid, i, j);\n            }\n        }\n    }\n    return count;\n}\n\nprivate void sink(char[][] g, int i, int j) {\n    if (i >= g.length || j >= g[i].length || g[i][j] != ''1'') return;\n    g[i][j] = ''0'';\n    sink(g, i + 1, j);\n    sink(g, i, j + 1);\n}', 0, '', 167, 2, 5, 6, 262, 42, '2', '111110', '[{"caseId":37,"pass":true},{"caseId":38,"pass":true},{"caseId":39,"pass":true},{"caseId":40,"pass":true},{"caseId":41,"pass":true},{"caseId":42,"pass":false,"output":"2"}]', 1700000000000000018, DATE_SUB(NOW(), INTERVAL 8032 MINUTE)),
