(1820000000000000653, 1700000000000000002, 1795000000000000115, NULL, 0, 'public int totalNQueens(int n) {\n    return place(n, 0, 0, 0, 0);\n}\n\nprivate int place(int n, int row, int cols, int d1, int d2) {\n    if (row == n) return 1;\n    int count = 0;\n    int free = ~(cols | d1 | d2) & ((1 << n) - 1);\n    while (free != 0) {\n        int bit = free & -free;\n        free -= bit;\n        count += place(n, row + 1, cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1);\n    }\n    return count;\n}', 1, '', 300, 1, 5, 5, 210, NULL, NULL, '11111', '[{"caseId":80,"pass":true},{"caseId":81,"pass":true},{"caseId":82,"pass":true},{"caseId":83,"pass":true},{"caseId":84,"pass":true}]', 1700000000000000002, DATE_SUB(NOW(), INTERVAL 6278 MINUTE)),
