(1820000000000000664, 1700000000000000011, 1795000000000000106, NULL, 0, 'public int search(int[] nums, int target) {\n    int lo = 0, hi = nums.length - 1;\n    while (lo <= hi) {\n        int mid = (lo + hi) >>> 1;\n        if (nums[mid] == target) return mid;\n        if (nums[mid] < target) lo = mid + 1; else hi = mid - 1;\n    }\n    return -1;\n}', 1, '', 100, 1, 5, 5, 271, NULL, NULL, '11111', '[{"caseId":32,"pass":true},{"caseId":33,"pass":true},{"caseId":34,"pass":true},{"caseId":35,"pass":true},{"caseId":36,"pass":true}]', 1700000000000000011, DATE_SUB(NOW(), INTERVAL 5280 MINUTE)),
(1820000000000000665, 1700000000000000016, 1795000000000000126, NULL, 0, 'public boolean isAnagram(String s, String t) {\n    if (s.length() != t.length()) return false;\n    int[] count = new int[26];\n    for (int i = 0; i < s.length(); i++) {\n        count[s.charAt(i) - ''a'']++;\n        count[t.charAt(i) - ''a'']--;\n    }\n    for (int c : count) {\n        if (c != 0) return false;\n    }\n    return true;\n}', 1, '', 100, 1, 6, 6, 237, NULL, NULL, '111111', '[{"caseId":146,"pass":true},{"caseId":147,"pass":true},{"caseId":148,"pass":true},{"caseId":149,"pass":true},{"caseId":150,"pass":true},{"caseId":151,"pass":true}]', 1700000000000000016, DATE_SUB(NOW(), INTERVAL 5165 MINUTE)),
(1820000000000000666, 1700000000000000020, 2102360449353351170, NULL, 0, 'public int numIslands(char[][] grid) {\n    int count = 0;\n    for (int i = 0; i < grid.length; i++) {\n        for (int j = 0; j < grid[i].length; j++) {\n            if (grid[i][j] == ''1'') {\n                count++;\n                sink(grid, i, j);\n            }\n        }\n    }\n    return count;\n}\n\nprivate void sink(char[][] g, int i, int j) {\n    if (i >= g.length || j >= g[i].length || g[i][j] != ''1'') return;\n    g[i][j] = ''0'';\n    sink(g, i + 1, j);\n    sink(g, i, j + 1);\n}', 0, '', 167, 2, 5, 6, 294, 42, '2', '111110', '[{"caseId":37,"pass":true},{"caseId":38,"pass":true},{"caseId":39,"pass":true},{"caseId":40,"pass":true},{"caseId":41,"pass":true},{"caseId":42,"pass":false,"output":"2"}]', 1700000000000000020, DATE_SUB(NOW(), INTERVAL 5106 MINUTE)),
