(1820000000000000670, 1700000000000000010, 1795000000000000112, NULL, 0, 'public int trap(int[] h) {\n    int l = 0, r = h.length - 1, lm = 0, rm = 0, water = 0;\n    while (l < r) {\n        if (h[l] < h[r]) {\n            lm = Math.max(lm, h[l]);\n            water += lm - h[l++];\n        } else {\n            rm = Math.max(rm, h[r]);\n            water += rm - h[r--];\n        }\n    }\n    return water\n}', 0, 'Solution.java:17: error: '';'' expected\n    return water\n                ^\n1 error\n', 0, 5, 0, 5, 28, NULL, NULL, '-----', '[{"caseId":65},{"caseId":66},{"caseId":67},{"caseId":68},{"caseId":69}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 4825 MINUTE)),
