(1820000000000000720, 1700000000000000017, 1795000000000000130, NULL, 0, 'public int[] maxSlidingWindow(int[] nums, int k) {\n    int[] r = new int[nums.length - k + 1];\n    Deque<Integer> dq = new ArrayDeque<>();\n    for (int i = 0; i < nums.length; i++) {\n        while (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();\n        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();\n        dq.offerLast(i);\n        if (i >= k - 1) r[i - k + 1] = nums[dq.peekFirst()];\n    }\n    return r;\n}', 1, '', 300, 1, 7, 7, 285, NULL, NULL, '1111111', '[{"caseId":170,"pass":true},{"caseId":171,"pass":true},{"caseId":172,"pass":true},{"caseId":173,"pass":true},{"caseId":174,"pass":true},{"caseId":175,"pass":true},{"caseId":176,"pass":true}]', 1700000000000000017, DATE_SUB(NOW(), INTERVAL 1900 MINUTE));
