(1820000000000000732, 1700000000000000006, 1795000000000000129, 1800000000000000104, 0, 'public int minPathSum(int[][] grid) {\n    int m = grid.length, n = grid[0].length;\n    int[] dp = new int[n];\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (i == 0 && j == 0) dp[j] = grid[0][0];\n            else if (i == 0) dp[j] = dp[j - 1] + grid[i][j];\n            else if (j == 0) dp[j] = dp[j] + grid[i][j];\n            else dp[j] = Math.min(dp[j], dp[j - 1]) + grid[i][j];\n        }\n    }\n    return dp[n - 1];\n}', 1, '', 200, 1, 6, 6, 317, NULL, NULL, '111111', '[{"caseId":164,"pass":true},{"caseId":165,"pass":true},{"caseId":166,"pass":true},{"caseId":167,"pass":true},{"caseId":168,"pass":true},{"caseId":169,"pass":true}]', 1700000000000000006, DATE_SUB(NOW(), INTERVAL 1419 MINUTE)),
