(1820000000000000735, 1700000000000000016, 1795000000000000129, 1800000000000000104, 0, 'public int minPathSum(int[][] grid) {\n    int i = 0, j = 0, sum = grid[0][0];\n    while (i < grid.length - 1 || j < grid[0].length - 1) {\n        if (i == grid.length - 1) j++;\n        else if (j == grid[0].length - 1) i++;\n        else if (grid[i + 1][j] < grid[i][j + 1]) i++;\n        else j++;\n        sum += grid[i][j];\n    }\n    return sum;\n}', 0, '', 133, 2, 4, 6, 256, 164, '9', '011110', '[{"caseId":164,"pass":false,"output":"9"},{"caseId":165,"pass":true},{"caseId":166,"pass":true},{"caseId":167,"pass":true},{"caseId":168,"pass":true},{"caseId":169,"pass":false,"output":"24"}]', 1700000000000000016, DATE_SUB(NOW(), INTERVAL 1399 MINUTE)),
