(1820000000000000743, 1700000000000000010, 1795000000000000108, NULL, 0, 'public int lengthOfLongestSubstring(String s) {\n    int[] last = new int[128];\n    Arrays.fill(last, -1);\n    int best = 0, left = 0;\n    for (int i = 0; i < s.length(); i++) {\n        char c = s.charAt(i);\n        left = Math.max(left, last[c] + 1);\n        last[c] = i;\n        best = Math.max(best, i - left + 1);\n    }\n    return best;\n}', 1, '', 200, 1, 7, 7, 295, NULL, NULL, '1111111', '[{"caseId":43,"pass":true},{"caseId":44,"pass":true},{"caseId":45,"pass":true},{"caseId":46,"pass":true},{"caseId":47,"pass":true},{"caseId":48,"pass":true},{"caseId":49,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 809 MINUTE)),
