(1820000000000000777, 1700000000000000009, 1795000000000000108, NULL, 0, 'public int lengthOfLongestSubstring(String s) {\n    int[] last = new int[128];\n    Arrays.fill(last, -1);\n    int best = 0, left = 0;\n    for (int i = 0; i < s.length(); i++) {\n        char c = s.charAt(i);\n        left = Math.max(left, last[c] + 1);\n        last[c] = i;\n        best = Math.max(best, i - left + 1);\n    }\n    return best;\n}', 1, '', 200, 1, 7, 7, 240, NULL, NULL, '1111111', '[{"caseId":43,"pass":true},{"caseId":44,"pass":true},{"caseId":45,"pass":true},{"caseId":46,"pass":true},{"caseId":47,"pass":true},{"caseId":48,"pass":true},{"caseId":49,"pass":true}]', 1700000000000000009, DATE_SUB(NOW(), INTERVAL 162 MINUTE)),
(1820000000000000778, 1700000000000000001, 1795000000000000116, NULL, 0, 'public int[] merge(int[] nums1, int[] nums2) {\n    int[] r = new int[nums1.length + nums2.length];\n    int i = 0, j = 0, k = 0;\n    while (i < nums1.length && j < nums2.length) {\n        r[k++] = nums1[i] <= nums2[j] ? nums1[i++] : nums2[j++];\n    }\n    while (i < nums1.length) r[k++] = nums1[i++];\n    while (j < nums2.length) r[k++] = nums2[j++];\n    return r;\n}', 1, '', 100, 1, 6, 6, 306, NULL, NULL, '111111', '[{"caseId":85,"pass":true},{"caseId":86,"pass":true},{"caseId":87,"pass":true},{"caseId":88,"pass":true},{"caseId":89,"pass":true},{"caseId":90,"pass":true}]', 1700000000000000001, DATE_SUB(NOW(), INTERVAL 69 MINUTE)),
(1820000000000000779, 1700000000000000011, 1795000000000000114, NULL, 0, 'public int longestValidParentheses(String s) {\n    Deque<Integer> stack = new ArrayDeque<>();\n    stack.push(-1);\n    int best = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s.charAt(i) == ''('') {\n            stack.push(i);\n        } else {\n            stack.pop();\n            if (stack.isEmpty()) stack.push(i);\n            else best = Math.max(best, i - stack.peek());\n        }\n    }\n    return best;\n}', 1, '', 300, 1, 5, 5, 318, NULL, NULL, '11111', '[{"caseId":75,"pass":true},{"caseId":76,"pass":true},{"caseId":77,"pass":true},{"caseId":78,"pass":true},{"caseId":79,"pass":true}]', 1700000000000000011, DATE_SUB(NOW(), INTERVAL 42 MINUTE)),
(1820000000000000780, 1700000000000000010, 1795000000000000114, NULL, 0, 'public int longestValidParentheses(String s) {\n    Deque<Integer> stack = new ArrayDeque<>();\n    stack.push(-1);\n    int best = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s.charAt(i) == ''('') {\n            stack.push(i);\n        } else {\n            stack.pop();\n            if (stack.isEmpty()) stack.push(i);\n            else best = Math.max(best, i - stack.peek());\n        }\n    }\n    return best;\n}', 1, '', 300, 1, 5, 5, 298, NULL, NULL, '11111', '[{"caseId":75,"pass":true},{"caseId":76,"pass":true},{"caseId":77,"pass":true},{"caseId":78,"pass":true},{"caseId":79,"pass":true}]', 1700000000000000010, DATE_SUB(NOW(), INTERVAL 28 MINUTE));
