INSERT IGNORE INTO `tb_submit_appeal` (`appeal_id`, `submit_id`, `user_id`, `question_id`, `exam_id`, `reason`, `ai_analysis`, `origin_judge_status`, `status`, `handle_by`, `handle_time`, `create_by`, `create_time`) VALUES
(1840000000000000001, 1820000000000000222, 1700000000000000004, 2102360449353351170, NULL, '我的 DFS 只往右和往下搜，示例都过了，第 6 个用例应该也是一座岛吧？怀疑用例有问题。', '学员代码只向右、向下扩展，遇到先往左上再连通的陆地会拆成两座岛，判题结果符合题意。', 2, 2, 1, DATE_SUB(NOW(), INTERVAL 33501 MINUTE), 1700000000000000004, DATE_SUB(NOW(), INTERVAL 33579 MINUTE)),
(1840000000000000002, 1820000000000000210, 1700000000000000016, 1795000000000000114, NULL, '输出 4 是按括号配对数算的，我觉得题目没说必须连续。', '题目要求的是最长连续有效子串，学员统计的是全部配对数，属于理解偏差；但题面对「连续」的强调不够醒目。', 2, 2, 1, DATE_SUB(NOW(), INTERVAL 34435 MINUTE), 1700000000000000016, DATE_SUB(NOW(), INTERVAL 34992 MINUTE)),
(1840000000000000003, 1820000000000000205, 1700000000000000009, 1795000000000000106, NULL, '只有一个元素的时候返回 -1，但我觉得我的循环没问题。', '循环条件为 lo < hi，区间只剩一个元素时直接退出，漏查了该元素，学员代码有误。', 2, 3, 1, DATE_SUB(NOW(), INTERVAL 35245 MINUTE), 1700000000000000009, DATE_SUB(NOW(), INTERVAL 35351 MINUTE)),
(1840000000000000004, 1820000000000000198, 1700000000000000001, 1795000000000000110, NULL, '贪心每次拿最大的硬币，结果和预期不一样，是不是预期输出错了？', '贪心在面额不成倍数关系时不是最优解，例如 [186,419,83,408]，预期输出正确。', 2, 3, 1, DATE_SUB(NOW(), INTERVAL 35433 MINUTE), 1700000000000000001, DATE_SUB(NOW(), INTERVAL 35879 MINUTE)),
(1840000000000000005, 1820000000000000341, 1700000000000000006, 1795000000000000111, NULL, '全是负数的时候我返回 0，题目没说子数组不能为空吧？', '题面写明子数组最少包含一个元素，全负数时应返回最大的那个负数；但提示位置较靠后，建议管理员确认题面是否需要加粗说明。', 2, 1, 1, DATE_SUB(NOW(), INTERVAL 27923 MINUTE), 1700000000000000006, DATE_SUB(NOW(), INTERVAL 27987 MINUTE)),
(1840000000000000006, 1820000000000000094, 1700000000000000018, 1796119683661783042, NULL, '负数取绝对值以后是回文的，我觉得应该算回文。', '题面明确负数不是回文数，学员取了绝对值，判题结果正确。', 2, 0, NULL, NULL, 1700000000000000018, DATE_SUB(NOW(), INTERVAL 116929 MINUTE)),
(1840000000000000007, 1820000000000000237, 1700000000000000002, 1795000000000000112, NULL, '我的思路和题解一样，只是写法不同，为什么答案错误？', '学员用全局最高柱子计算每个位置的积水，会高估两侧较矮区域的水量，判题结果正确。', 2, 0, NULL, NULL, 1700000000000000002, DATE_SUB(NOW(), INTERVAL 32198 MINUTE));
